import React, { useState, useEffect, useMemo } from "react";

/** * 🎨 THEME & CONSTANTS 
 */
const COLORS = {
  primary: "#4F46E5",
  primaryHover: "#4338CA",
  success: "#10B981",
  danger: "#EF4444",
  warning: "#F59E0B",
  background: "#F8FAFC",
  surface: "#FFFFFF",
  textMain: "#1E293B",
  textMuted: "#64748B",
  border: "#E2E8F0"
};

/**
 * 🛠️ MINI-COMPOSANTS INTERNES (UI KIT)
 */
const Card = ({ children, title, subtitle, action }) => (
  <div style={styles.card}>
    <div style={styles.cardHeader}>
      <div>
        <h3 style={styles.cardTitle}>{title}</h3>
        {subtitle && <p style={styles.cardSubtitle}>{subtitle}</p>}
      </div>
      {action && <div>{action}</div>}
    </div>
    <div style={styles.cardBody}>{children}</div>
  </div>
);

const Badge = ({ status }) => {
  const getStyle = () => {
    switch(status) {
      case 'Present': return { bg: "#DCFCE7", text: "#166534" };
      case 'Late': return { bg: "#FEF3C7", text: "#92400E" };
      default: return { bg: "#F1F5F9", text: "#475569" };
    }
  };
  const colors = getStyle();
  return (
    <span style={{
      ...styles.badge,
      backgroundColor: colors.bg,
      color: colors.text
    }}>{status}</span>
  );
};

/**
 * 📊 COMPOSANT : DASHBOARD (VUE 1)
 */
const AdvancedDashboard = ({ students }) => {
  const stats = useMemo(() => [
    { label: "Total Étudiants", value: students.length, icon: "👥", color: "#4F46E5" },
    { label: "Présents aujourd'hui", value: students.filter(s => s.status === 'Present').length, icon: "✅", color: "#10B981" },
    { label: "Retards", value: "3", icon: "⏰", color: "#F59E0B" },
    { label: "Taux de présence", value: "94%", icon: "📈", color: "#8B5CF6" },
  ], [students]);

  return (
    <div style={styles.viewContainer}>
      <div style={styles.statsGrid}>
        {stats.map((stat, i) => (
          <div key={i} style={styles.statCard}>
            <div style={{...styles.statIcon, backgroundColor: stat.color + '15', color: stat.color}}>{stat.icon}</div>
            <div>
              <p style={styles.statLabel}>{stat.label}</p>
              <h4 style={styles.statValue}>{stat.value}</h4>
            </div>
          </div>
        ))}
      </div>

      <Card title="Journal de présence récent" subtitle="Les 10 dernières entrées détectées par l'IA">
        <table style={styles.table}>
          <thead>
            <tr style={styles.tableHeader}>
              <th style={styles.th}>Étudiant</th>
              <th style={styles.th}>Heure</th>
              <th style={styles.th}>Méthode</th>
              <th style={styles.th}>Statut</th>
            </tr>
          </thead>
          <tbody>
            {students.map((student) => (
              <tr key={student.id} style={styles.tableRow}>
                <td style={styles.td}>
                  <div style={styles.userCell}>
                    <div style={styles.avatar}>{student.name.charAt(0)}</div>
                    <div>
                      <div style={{fontWeight: 600}}>{student.name}</div>
                      <div style={{fontSize: '0.75rem', color: COLORS.textMuted}}>{student.id}</div>
                    </div>
                  </div>
                </td>
                <td style={styles.td}>{student.lastSeen}</td>
                <td style={styles.td}>Face ID</td>
                <td style={styles.td}><Badge status={student.status} /></td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>
    </div>
  );
};

/**
 * ➕ COMPOSANT : FORMULAIRE D'ENRÔLEMENT (VUE 2)
 */
const AdvancedEnrollment = ({ onAdd }) => {
  const [form, setForm] = useState({ name: "", email: "", role: "Student" });

  const handleSubmit = (e) => {
    e.preventDefault();
    onAdd({ ...form, id: `STU-${Math.floor(Math.random()*1000)}`, status: "Present", lastSeen: "À l'instant" });
    setForm({ name: "", email: "", role: "Student" });
  };

  return (
    <div style={styles.viewContainer}>
      <Card title="Ajouter un nouvel utilisateur" subtitle="L'IA analysera le visage après validation des informations">
        <form onSubmit={handleSubmit} style={styles.form}>
          <div style={styles.formGroup}>
            <label style={styles.label}>Nom complet</label>
            <input 
              style={styles.input} 
              placeholder="Ex: Jean Dupont" 
              value={form.name}
              onChange={e => setForm({...form, name: e.target.value})}
              required
            />
          </div>
          <div style={styles.formGroup}>
            <label style={styles.label}>Adresse Email</label>
            <input 
              style={styles.input} 
              type="email" 
              placeholder="jean@ecole.com"
              value={form.email}
              onChange={e => setForm({...form, email: e.target.value})}
              required 
            />
          </div>
          <div style={{display: 'flex', gap: '20px'}}>
            <div style={{...styles.formGroup, flex: 1}}>
              <label style={styles.label}>Rôle</label>
              <select style={styles.input} value={form.role} onChange={e => setForm({...form, role: e.target.value})}>
                <option>Étudiant</option>
                <option>Professeur</option>
                <option>Staff</option>
              </select>
            </div>
            <div style={{...styles.formGroup, flex: 1}}>
              <label style={styles.label}>Groupe / Classe</label>
              <input style={styles.input} placeholder="Ex: Master 1" />
            </div>
          </div>
          <button type="submit" style={styles.primaryBtn}>🚀 Initialiser l'enrôlement</button>
        </form>
      </Card>
    </div>
  );
};

/**
 * 🎥 COMPOSANT : CAMERA RECOGNITION (VUE 3)
 */
const SmartCamera = () => {
  const [scanning, setScanning] = useState(true);

  return (
    <div style={styles.viewContainer}>
      <div style={styles.cameraWrapper}>
        <div style={styles.cameraFrame}>
          <div style={styles.videoPlaceholder}>
            {scanning && <div style={styles.scanLine} />}
            <span style={{zIndex: 2, color: 'white'}}>Flux Vidéo en Direct...</span>
          </div>
          <div style={styles.cameraOverlay}>
             <div style={styles.targetBox} />
          </div>
        </div>
        <div style={styles.cameraSidebar}>
          <Card title="Analyse IA">
            <div style={styles.logContainer}>
              <div style={styles.logItem}>📡 Recherche de visages...</div>
              <div style={styles.logSuccess}>✅ Visage détecté : 0.98 certitude</div>
              <div style={styles.logItem}>🔍 Comparaison base de données...</div>
              <div style={styles.logHighlight}>👤 Utilisateur : Jean Dupont</div>
              <div style={styles.logSuccess}>🔓 Accès Autorisé - 08:45</div>
            </div>
            <button 
              onClick={() => setScanning(!scanning)} 
              style={{...styles.primaryBtn, marginTop: '20px', backgroundColor: scanning ? COLORS.danger : COLORS.success}}
            >
              {scanning ? "Arrêter le scan" : "Démarrer le scan"}
            </button>
          </Card>
        </div>
      </div>
    </div>
  );
};

/**
 * 🏁 MAIN APP COMPONENT
 */
export default function App() {
  const [currentView, setCurrentView] = useState("dashboard");
  const [notifications, setNotifications] = useState([]);
  const [students, setStudents] = useState([
    { id: "STU-882", name: "Alice Vasseur", status: "Present", lastSeen: "08:30" },
    { id: "STU-451", name: "Marc Aubert", status: "Late", lastSeen: "09:12" },
    { id: "STU-102", name: "Sophie Lefebvre", status: "Present", lastSeen: "08:15" },
  ]);

  const addNotification = (text) => {
    const id = Date.now();
    setNotifications([...notifications, { id, text }]);
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 3000);
  };

  const addStudent = (newStudent) => {
    setStudents([newStudent, ...students]);
    addNotification(`Succès: ${newStudent.name} a été enrôlé !`);
    setCurrentView("dashboard");
  };

  return (
    <div style={styles.appWrapper}>
      {/* Sidebar de navigation Pro */}
      <aside style={styles.sidebar}>
        <div style={styles.brand}>
          <div style={styles.brandIcon}>Σ</div>
          <h2 style={styles.brandName}>Attendance OS</h2>
        </div>
        
        <nav style={styles.sideNav}>
          <NavItem active={currentView === 'dashboard'} onClick={() => setCurrentView('dashboard')} icon="📊" label="Dashboard" />
          <NavItem active={currentView === 'enroll'} onClick={() => setCurrentView('enroll')} icon="➕" label="Enrôlement" />
          <NavItem active={currentView === 'camera'} onClick={() => setCurrentView('camera')} icon="📷" label="Reconnaissance" />
          <div style={styles.navDivider} />
          <NavItem icon="⚙️" label="Paramètres" />
          <NavItem icon="📄" label="Rapports PDF" />
        </nav>

        <div style={styles.userProfile}>
          <div style={styles.avatar}>A</div>
          <div style={{marginLeft: '10px'}}>
            <div style={{fontWeight: 600, fontSize: '0.9rem'}}>Admin Prof</div>
            <div style={{fontSize: '0.75rem', color: '#94A3B8'}}>Superuser</div>
          </div>
        </div>
      </aside>

      {/* Zone principale */}
      <main style={styles.main}>
        <header style={styles.topBar}>
          <div style={styles.searchBar}>
            <span>🔍</span>
            <input style={styles.searchInp} placeholder="Rechercher un étudiant, une date..." />
          </div>
          <div style={styles.topActions}>
            <button style={styles.iconBtn}>🔔</button>
            <button style={styles.iconBtn}>🌙</button>
          </div>
        </header>

        <div style={styles.content}>
          <header style={{marginBottom: '30px'}}>
            <h1 style={styles.pageTitle}>
              {currentView === 'dashboard' && "Vue d'ensemble"}
              {currentView === 'enroll' && "Nouvel Étudiant"}
              {currentView === 'camera' && "Scanner IA en direct"}
            </h1>
            <p style={{color: COLORS.textMuted}}>Système de surveillance biométrique actif.</p>
          </header>

          {currentView === "dashboard" && <AdvancedDashboard students={students} />}
          {currentView === "enroll" && <AdvancedEnrollment onAdd={addStudent} />}
          {currentView === "camera" && <SmartCamera />}
        </div>
      </main>

      {/* Notifications Toast */}
      <div style={styles.toastContainer}>
        {notifications.map(n => (
          <div key={n.id} style={styles.toast}>{n.text}</div>
        ))}
      </div>
    </div>
  );
}

const NavItem = ({ active, icon, label, onClick }) => (
  <div 
    onClick={onClick}
    style={{
      ...styles.navItem,
      backgroundColor: active ? COLORS.primary + '10' : 'transparent',
      color: active ? COLORS.primary : COLORS.textMuted,
      borderLeft: active ? `4px solid ${COLORS.primary}` : '4px solid transparent'
    }}
  >
    <span style={{marginRight: '12px', fontSize: '1.2rem'}}>{icon}</span>
    {label}
  </div>
);

